<script lang="ts">
 import type {DatabaseCatalog} from "./database-catalog";import {Database,Plus,FolderOpen,ArrowRight,Home} from "@lucide/svelte";import {translator} from "./i18n";
 export let catalog:DatabaseCatalog;export let language:"ru"|"ro";export let active="default";export let onopen:(id:string)=>Promise<void>;export let onnew:(name:string)=>Promise<void>;export let onimport:()=>Promise<void>;export let onauto:(id:string|null)=>Promise<void>;export let onresume:()=>void;
 let name="",busy=false; $:t=translator(language);
 async function open(id:string){busy=true;try{await onopen(id);}finally{busy=false;}}
</script>
<div class="database-home">
 <aside><img src="/brand/logo-full.svg" alt="OpenHaU OPEN"/><button class="button" disabled={busy} onclick={()=>{const input=document.getElementById("database-new-name");input?.focus();}}><Plus size={18}/>{t("Создать базу","Creează o bază")}</button><button class="button secondary" disabled={busy} onclick={onimport}><FolderOpen size={18}/>{t("Открыть JSON","Deschide JSON")}</button><button class="button secondary" disabled={busy} onclick={onresume}><Home size={18}/>{t("Рабочая область","Spațiu de lucru")}</button></aside>
 <section><h1>{t("Базы данных","Baze de date")}</h1><div class="database-create"><input id="database-new-name" aria-label={t("Название новой базы","Denumirea bazei noi")} placeholder={t("Название новой базы","Denumirea bazei noi")} bind:value={name}/><button class="button" disabled={busy||!name.trim()} onclick={async()=>{busy=true;try{await onnew(name);name="";}finally{busy=false;}}}><Plus size={16}/>{t("Создать","Creează")}</button></div><div class="database-cards">{#each catalog.databases as db}<button class="database-card" disabled={busy} onclick={()=>open(db.id)}><Database size={32}/><strong>{db.name}</strong>{#if active===db.id}<small>{t("Текущая база","Baza curentă")}</small>{/if}<span><ArrowRight size={18}/>{t("Открыть","Deschide")}</span></button>{/each}</div><label>{t("Автоматически открывать при запуске","Deschidere automată la pornire")}<select value={catalog.auto||""} onchange={e=>onauto(e.currentTarget.value||null)}><option value="">{t("Показывать выбор базы","Afișează alegerea bazei")}</option>{#each catalog.databases as db}<option value={db.id}>{db.name}</option>{/each}</select></label></section>
</div>
<style>.database-home{display:grid;grid-template-columns:220px minmax(0,1fr);height:100%;overflow:auto}.database-home aside{display:flex;flex-direction:column;gap:16px;padding:30px 18px;background:var(--sidebar);border-right:1px solid var(--border)}aside img{width:130px;margin:0 auto 28px;opacity:.8;filter:brightness(0)}:global(:root[data-theme="dark"]) aside img{filter:none}.database-home section{padding:36px;overflow:auto}.database-home h1{font-size:26px;font-weight:400;margin:0 0 30px}.database-create{display:flex;gap:12px;max-width:650px}.database-create input{flex:1;min-width:0}.database-cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:24px;margin:30px 0}.database-card{display:flex;flex-direction:column;gap:16px;align-items:flex-start;text-align:left;padding:24px;background:transparent;border:1px solid transparent;color:var(--text);min-height:180px}.database-card:hover{border-color:var(--reveal-ink,#0002);background:var(--hover)}.database-card>:global(svg),.database-card>span{color:var(--accent)}.database-card span{display:flex;gap:8px;align-items:center}.database-home label{display:flex;flex-direction:column;gap:12px;max-width:440px}.database-home small{color:var(--muted)}</style>
